package com.hotel.dto;
import java.time.LocalDate; import java.time.LocalDateTime;
public record CustomerFormDto(Long id,String fullName,String email,String phone,LocalDate dateOfBirth,String idDocumentType,String idDocumentNumber,String nationality,String address,LocalDateTime version){public Long getId(){return id;} public String getFullName(){return fullName;} public String getEmail(){return email;} public String getPhone(){return phone;} public LocalDate getDateOfBirth(){return dateOfBirth;} public String getIdDocumentType(){return idDocumentType;} public String getIdDocumentNumber(){return idDocumentNumber;} public String getNationality(){return nationality;} public String getAddress(){return address;} public LocalDateTime getVersion(){return version;}}
